export async function readPage(input, api) {
  const path = input.path;
  if (typeof path !== 'string' || !path.startsWith('/') || path.startsWith('//') || /[\\#\u0000-\u0020\u007f]/.test(path)) {
    throw new Error('invalid-path');
  }
  const url = 'https://example.com' + path;
  const response = await api.network.request({ url, method: 'GET' });
  const characters = Array.from(response.body);
  const preview = characters.slice(0, 6000).join('').replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f-\u009f]/g, '\uFFFD');
  await api.ui.present({ view: {
    title: '公开页面预览',
    blocks: [
      { type: 'status', tone: response.ok ? 'success' : 'warning', text: 'HTTP ' + response.status + (response.ok ? '：已收到响应。' : '：服务返回非成功状态。') },
      { type: 'fields', items: [
        { label: '地址', value: url },
        { label: '内容类型', value: response.contentType || '未提供' }
      ] },
      { type: 'code', language: 'text', code: preview },
      { type: 'text', text: '内容按纯文本展示，不执行网页代码。'
        + (characters.length > 6000 ? '这里只显示前 6000 个字符。' : '正文已完整展示。')
        + '不支持显示的控制字符替换为 �。没有写入草稿、生成文件或调用模型。' }
    ],
    actions: []
  } });
  return { status: response.status, ok: response.ok, shownCharacters: Math.min(characters.length, 6000) };
}
